INSERT INTO "public"."site_pages" ("id", "org_id", "slug", "kind", "title", "subtitle", "hero_image", "body", "is_active", "show_in_nav", "display_order", "updated_at") VALUES
	('ea53abb9-e3f8-4745-8798-4bb8311f4cea', '00000000-0000-0000-0000-000000000001', 'guide-eyeglasses', 'guide', 'Frame Size Guide', 'Find the frame that fits your face', NULL, '{"table": {"rows": [["Narrow", "44–48", "16–18", "130–135"], ["Medium", "49–53", "17–19", "135–140"], ["Wide", "54–58", "18–20", "140–150"]], "headers": ["Fit", "Lens width", "Bridge", "Temple"]}, "sections": [{"body": "Three numbers are printed inside the temple arm, e.g. 52-18-140: lens width, bridge width and temple length (mm).", "heading": "Read your frame size"}, {"body": "Hold a ruler across your cheekbones. Under 125mm is narrow, 125–135mm medium, above 135mm wide.", "heading": "Measure your face"}]}', true, false, 10, '2026-11-22 06:05:08.117666+00'),
	('62a0c312-b563-4ad6-aef6-af6a86b861ca', '00000000-0000-0000-0000-000000000001', 'guide-sunglasses', 'guide', 'Sunglasses Guide', 'Protection and style, explained', NULL, '{"sections": [{"body": "Look for UV400 so both UVA and UVB rays are blocked.", "heading": "UV400 protection"}, {"body": "Cut glare from roads and water, ideal for driving and travel.", "heading": "Polarised lenses"}, {"body": "Grey keeps true colour, brown boosts contrast, green is balanced for everyday wear.", "heading": "Lens colour"}]}', true, false, 11, '2026-11-22 06:05:08.117666+00'),
	('4f658442-6ebb-48e5-803f-c88595c13c34', '00000000-0000-0000-0000-000000000001', 'guide-contact-lenses', 'guide', 'Contact Lens Guide', 'Choose the right lenses', NULL, '{"sections": [{"body": "Dailies are thrown away each night for maximum hygiene. Monthlies are economical with a care routine.", "heading": "Daily vs monthly"}, {"body": "Toric lenses correct astigmatism and need a fitting.", "heading": "Astigmatism"}, {"body": "Contact lens power differs from spectacle power. Book a fitting if you are new to lenses.", "heading": "Prescription needed"}]}', true, false, 12, '2026-11-22 06:05:08.117666+00'),
	('9eb0d556-9e98-492c-af58-3227b0655555', '00000000-0000-0000-0000-000000000001', 'guide-computer-glasses', 'guide', 'Computer Glasses Guide', 'Comfort for long screen hours', NULL, '{"sections": [{"body": "Reduces high-energy blue light from screens, helping with eye strain and sleep.", "heading": "Blue-light filter"}, {"body": "Every 20 minutes look at something 20 feet away for 20 seconds.", "heading": "20-20-20 rule"}, {"body": "Cuts screen glare so text looks crisper.", "heading": "Anti-reflective coating"}]}', true, false, 13, '2026-11-22 06:05:08.117666+00'),
	('f49329ca-4704-4207-a280-dd8829f06bb5', '00000000-0000-0000-0000-000000000001', 'guide-lenses', 'guide', 'Lens & Coating Guide', 'Index, designs and coatings', NULL, '{"sections": [{"body": "Higher index means thinner, lighter lenses. Choose 1.67 or 1.74 for strong powers.", "heading": "Lens index"}, {"body": "Single vision for one distance, bifocal or progressive for near and far.", "heading": "Designs"}, {"body": "Anti-glare, scratch-resistant, hydrophobic and blue-cut coatings extend life and comfort.", "heading": "Coatings"}]}', true, false, 14, '2026-11-22 06:05:08.117666+00'),
	('250db7ef-cbf4-4583-ab70-98cd86b49cb9', '00000000-0000-0000-0000-000000000001', 'about', 'page', 'About Us', 'Caring for your eyes since 1998', NULL, '{"stats": [{"label": "Years of trust", "value": "25+"}, {"label": "Stores", "value": "2"}, {"label": "Genuine brands", "value": "100%"}], "sections": [{"body": "Power Eyes Opticals began in Mogappair, Chennai, with one promise: honest, expert eye care for every family.", "heading": "Our story"}, {"body": "Authentic brands, transparent pricing, free lifetime adjustments and complete prescription privacy.", "heading": "What we stand for"}]}', true, true, 1, '2026-11-22 06:05:08.117666+00'),
	('93255823-9f0a-4786-bada-59d87eed18af', '00000000-0000-0000-0000-000000000001', 'clinic', 'page', 'Our Eye Clinic', 'Clinic-grade eye testing in-store', NULL, '{"sections": [{"body": "Auto-refraction, subjective refinement, binocular vision checks and eye-health screening by qualified optometrists.", "heading": "Comprehensive eye test"}, {"body": "Trial lenses, handling training and follow-ups.", "heading": "Contact lens fitting"}, {"body": "Gentle, child-friendly testing and myopia guidance.", "heading": "Children''s eye care"}]}', true, true, 2, '2026-11-22 06:05:08.117666+00'),
	('b7430392-4512-4254-bebe-78aa7dee9b7f', '00000000-0000-0000-0000-000000000001', 'lab', 'page', 'Our Lab', 'Precision lenses, made in-house', NULL, '{"sections": [{"body": "Digital centration and computer-controlled edging for accurate fitting.", "heading": "Precision edging"}, {"body": "Every pair passes power, axis, coating and cosmetic inspection before delivery.", "heading": "Quality checks"}, {"body": "Most single-vision orders are ready within 24–48 hours.", "heading": "Fast turnaround"}]}', true, true, 3, '2026-11-22 06:05:08.117666+00'),
	('4149999d-757e-43eb-b164-36d9dbc0feb6', '00000000-0000-0000-0000-000000000001', 'eye-consultation', 'config', 'Eye Consultation', 'Book a professional eye test', NULL, '{"cta": "Confirm via WhatsApp", "note": "We confirm within 30 minutes.", "intro": "Professional eye care at our stores.", "price": "", "times": ["09:30 AM", "10:00 AM", "10:30 AM", "11:00 AM", "02:00 PM", "02:30 PM", "03:00 PM", "04:00 PM", "04:30 PM"], "types": ["Comprehensive Eye Test", "Contact Lens Fitting", "Follow Up", "Consultation"], "duration": "30 min", "closed_weekdays": []}', true, false, 4, '2026-11-22 06:05:08.117666+00'),
	('f1e3e8b0-0351-42b7-a60f-27d719272a7a', '00000000-0000-0000-0000-000000000001', 'hero-eyeglasses', 'config', 'Eyeglasses', 'Prescription frames for every face and lifestyle', NULL, '{}', true, false, 20, '2026-11-22 06:05:08.117666+00'),
	('71b5646f-fa39-4706-a043-f50469ca0e14', '00000000-0000-0000-0000-000000000001', 'hero-sunglasses', 'config', 'Sunglasses', 'Style meets protection – regular & prescription sunglasses', NULL, '{}', true, false, 21, '2026-11-22 06:05:08.117666+00'),
	('20e25613-cf9b-44aa-a132-d88b080140cf', '00000000-0000-0000-0000-000000000001', 'hero-contact-lenses', 'config', 'Contact Lenses', 'Daily, monthly and coloured lenses from leading brands', NULL, '{}', true, false, 22, '2026-11-22 06:05:08.117666+00'),
	('799ef48b-2da5-4398-bf1f-8484fa8cba8d', '00000000-0000-0000-0000-000000000001', 'hero-computer-glasses', 'config', 'Computer & Blue Light Glasses', 'Protect your eyes from digital strain', NULL, '{}', true, false, 23, '2026-11-22 06:05:08.117666+00'),
	('145e649a-ca85-4195-9a02-1e6bd025a8a7', '00000000-0000-0000-0000-000000000001', 'hero-lenses', 'config', 'Lens & Coatings', 'Choose the right index, design and coating', NULL, '{}', true, false, 24, '2026-11-22 06:05:08.117666+00'),
	('4ea6b7d6-8fca-48c5-9956-86a3e0dac41e', '00000000-0000-0000-0000-000000000001', 'privacy', 'page', 'Privacy Policy', 'How we collect, use and protect your data', NULL, '{"sections": [{"body": "When you use the Power Eyes Opticals website or visit our stores, we collect information you provide directly: your name, phone number and email address when you create an account or place an order; your eye prescription (SPH, CYL, Axis, ADD, PD) when you upload a prescription or book a lens order; your delivery address when you choose home delivery; your payment method details, which are processed securely by Razorpay and never stored on our servers; and any messages you send us via our contact form or WhatsApp.\n\nWe also collect information automatically: pages visited, time spent on each page, browser type and device type through standard web analytics.", "heading": "Information We Collect"}, {"body": "We use your information to process and fulfil your orders, send order confirmations and status updates via WhatsApp and email, prepare your prescription lenses accurately and safely, communicate with you about appointments you book, send you information about offers and promotions if you have opted in, improve our website and services, and comply with legal obligations.\n\nYour prescription information is used only for fulfilling your lens order. It is shared with our lens laboratory partners only to the extent necessary to manufacture your lenses.", "heading": "How We Use Your Information"}, {"body": "Your eye prescription is sensitive health information. We treat it with the highest level of care. Your prescription is stored securely in our database and is accessible only to you through your Vision ID and to our trained optometrists and dispensing staff.\n\nWe do not sell, rent or share your prescription data with any third party for marketing purposes. Our lab partners receive only the prescription values necessary to manufacture your lenses and are contractually required to delete that data after production.", "heading": "Eye Prescription Data"}, {"body": "We share your information only in these limited circumstances: with Razorpay to process your payment; with our lens laboratory to manufacture your prescription lenses; with courier partners to deliver your order; with legal or regulatory authorities if required by law.\n\nWe do not sell your personal information to any third party.", "heading": "Sharing Your Information"}, {"body": "We use industry-standard security measures including HTTPS encryption for all data transmission, secure database hosting via Supabase on AWS infrastructure, password hashing and secure session management, and regular security reviews.\n\nPayment card details are never stored on our servers — all payments are handled directly by Razorpay, which is PCI-DSS Level 1 certified.", "heading": "Data Security"}, {"body": "Our website uses cookies for essential functions (keeping you logged in, remembering your cart) and analytics (understanding how visitors use our site via anonymous statistics). You can disable non-essential cookies in your browser settings without affecting core site functionality.", "heading": "Cookies"}, {"body": "You have the right to access the personal information we hold about you, correct any inaccurate information, request deletion of your account and associated data, opt out of marketing communications at any time, and download your prescription data.\n\nTo exercise any of these rights, email us at powereyes.chennai@gmail.com or contact us via WhatsApp on 9840496404.", "heading": "Your Rights"}, {"body": "We may update this privacy policy from time to time. We will notify registered customers of significant changes via email or WhatsApp. Continued use of our website after a change constitutes acceptance of the updated policy.", "heading": "Changes to This Policy"}]}', true, false, 30, '2026-11-22 06:05:08.117666+00'),
	('acdd121d-dfac-405c-b587-b2f3b19f3b1e', '00000000-0000-0000-0000-000000000001', 'terms', 'page', 'Terms of Service', 'The terms that apply when you use our website and stores', NULL, '{"sections": [{"body": "By using the Power Eyes Opticals website (powereyes.in) or purchasing from our stores, you agree to these Terms of Service. If you do not agree, please do not use our website.", "heading": "Acceptance of Terms"}, {"body": "All product prices are displayed in Indian Rupees (₹) and are inclusive of GST unless stated otherwise. Prices are subject to change without notice. In the event of a pricing error, we reserve the right to cancel the order and refund the amount paid. Product images are for illustration — actual colour and dimensions may vary slightly.", "heading": "Products and Pricing"}, {"body": "You are responsible for providing an accurate, current prescription. Power Eyes Opticals will manufacture lenses based on the prescription you provide. We are not liable for vision problems resulting from an inaccurate prescription supplied by the customer. Prescriptions must be issued by a registered optometrist or ophthalmologist and must be valid (within 2 years for glasses, 1 year for contact lenses).", "heading": "Prescription Accuracy"}, {"body": "Placing an order constitutes an offer to purchase. We reserve the right to accept or decline any order. Full payment is required at the time of online order placement. For high-value or custom orders, we may require an advance payment confirmation before beginning production.", "heading": "Orders and Payment"}, {"body": "Delivery timelines are estimates, not guarantees. Power Eyes Opticals is not responsible for delays caused by courier partners, natural events or circumstances beyond our control. Risk of damage or loss passes to the customer upon delivery confirmation.", "heading": "Delivery"}, {"body": "Unworn frames may be returned within 7 days of purchase with original bill and packaging. Prescription lenses are custom-made and cannot be returned unless there is a manufacturing defect. If the lenses do not match the prescription you provided, we will remake them within 30 days at no charge. Hygiene products (contact lenses, nose pads) are non-returnable once opened.", "heading": "Returns and Exchanges"}, {"body": "All content on this website including text, images, logos, and design is the property of Power Eyes Opticals. You may not reproduce, copy or distribute any content without prior written permission.", "heading": "Intellectual Property"}, {"body": "Power Eyes Opticals is not liable for any indirect, incidental or consequential damages arising from the use of our products or website. Our liability is limited to the value of the order in question. This does not affect your statutory rights under the Consumer Protection Act 2019.", "heading": "Limitation of Liability"}, {"body": "These terms are governed by the laws of India. Any disputes arising from these terms or your use of our website shall be subject to the exclusive jurisdiction of courts in Chennai, Tamil Nadu.", "heading": "Governing Law"}]}', true, false, 31, '2026-11-22 06:05:08.117666+00'),
	('fcda22dd-6a15-43b5-8a75-b9f43bc2e0a4', '00000000-0000-0000-0000-000000000001', 'faq', 'page', 'Frequently Asked Questions', 'Quick answers about eye tests, frames, lenses and orders', NULL, '{"faq": [{"items": [{"a": "Yes. A comprehensive eye test at both our Mogappair stores is completely free, with no obligation to purchase. We use digital auto-refractors for accurate results.", "q": "Is the eye test free?"}, {"a": "A standard comprehensive eye test takes 20–30 minutes. Contact lens fittings and children''s tests may take slightly longer.", "q": "How long does an eye test take?"}, {"a": "Adults with no known issues: every 2 years. Children: annually. If you wear glasses or contact lenses, or have a family history of eye disease, annually is recommended.", "q": "How often should I get my eyes tested?"}, {"a": "Yes. We accept valid prescriptions from any registered ophthalmologist or optometrist. The prescription must be less than 2 years old for glasses and 1 year old for contact lenses.", "q": "Can I bring my existing prescription from another clinic?"}, {"a": "Yes. We offer specialist children''s eye tests (below 16 years) free of charge. We recommend first eye test at age 3–4, then annually through school years.", "q": "Do you test children''s eyes?"}], "title": "Eye Testing"}, {"items": [{"a": "Single vision glasses: 2–3 working days. Progressive / bifocal lenses: 5–7 working days. High-power prescriptions may take longer. You''ll receive a WhatsApp message when ready.", "q": "How long does it take to get my glasses ready?"}, {"a": "Yes. We deliver across Chennai and major Indian cities. Free shipping on orders above ₹999. Express delivery (1–2 days) is available for ₹99.", "q": "Do you offer home delivery?"}, {"a": "Yes. Store pickup is always free. Choose ''Store Pickup'' at checkout and select your preferred store (Mogappair East or Mogappair West). We''ll WhatsApp you when your order is ready.", "q": "Can I pick up from the store?"}, {"a": "Yes. Upload a photo of your prescription during checkout, or enter values manually. Our optometrist reviews every prescription before the order goes to the lab.", "q": "Can I order glasses online with my prescription?"}], "title": "Ordering & Delivery"}, {"items": [{"a": "Yes. 100% of products sold at Power Eyes Opticals are purchased from authorised distributors. We do not sell grey market, parallel import or counterfeit products.", "q": "Are all products genuine?"}, {"a": "Our lens recommendation engine selects the right index based on your prescription. As a guide: mild powers (up to ±2D) use 1.56 standard; moderate (±2–4D) use 1.60; high (±4–6D) use 1.67; very high (above ±6D) use 1.74.", "q": "What lens index should I choose?"}, {"a": "Yes. We offer single vision, progressive, bifocal and occupational lenses. Progressive lenses are available from ₹3,990 with anti-reflective coating included.", "q": "Do you offer progressive lenses?"}, {"a": "Yes. Blue light filter is available as an add-on for all lens packages. We recommend it for customers who spend 4+ hours daily on screens.", "q": "Can I add blue light filtering to any lens?"}, {"a": "Yes. We stock daily, monthly, toric and coloured contact lenses from brands including Alcon, Johnson & Johnson and Bausch & Lomb. A contact lens fitting is required for first-time wearers.", "q": "Do you sell contact lenses?"}], "title": "Products & Lenses"}, {"items": [{"a": "You can return or exchange unworn frames within 7 days of purchase with the original bill. Prescription lenses cannot be returned unless there is a manufacturing defect. If your prescription was wrong, we will remake the lenses free of charge within 30 days.", "q": "What is your return policy?"}, {"a": "All frames come with a 1-year manufacturing warranty covering defects in material and workmanship — hinge failures, coating peeling and nose pad defects. It does not cover accidental damage, scratches from normal use or lost frames.", "q": "What does the warranty cover?"}, {"a": "We offer free adjustments for life on all frames purchased from us. Scratched lenses can be replaced at a discount — bring your original frame and prescription to any store.", "q": "What if my lenses are scratched?"}], "title": "Returns & Warranty"}, {"items": [{"a": "Online: UPI (Google Pay, PhonePe, Paytm), Credit/Debit Card, Net Banking via Razorpay. In-store: Cash, UPI, card. We also accept partial advance payment for prescription lens orders.", "q": "What payment methods do you accept?"}, {"a": "Yes. All online payments are processed through Razorpay, which is PCI-DSS Level 1 compliant. We never store your card details.", "q": "Is online payment secure?"}], "title": "Payments"}]}', true, false, 33, '2026-11-22 06:05:08.117666+00'),
	('dbad7f53-3e57-4c77-a984-8f0e8e6e373f', '00000000-0000-0000-0000-000000000001', 'returns', 'page', 'Returns & Exchange', 'Simple, hassle-free returns', NULL, '{"extra": {"icon": "✗", "items": ["Accidental damage, scratches, breakage after delivery", "Frames with signs of wear or alteration", "Items returned after 7 days (unless manufacturing defect)", "Customised or engraved products", "Prescription lenses (custom-made for your eyes)", "Opened contact lens boxes"], "heading": "What''s NOT Covered"}, "callout": {"text": "Return unworn frames within 7 days for a full refund — no questions asked.", "title": "7-Day Easy Returns on Frames"}, "sections": [{"icon": "✅", "items": ["Unworn and undamaged frames only", "Original bill and packaging required", "Return to any Power Eyes store in person", "Full refund to original payment method within 5–7 business days", "Exchange for a different frame of equal or higher value (pay difference)"], "heading": "Frames — 7 Day Return"}, {"icon": "🔭", "items": ["Prescription lenses are custom-made for your eyes and cannot be returned", "If lenses do not match the prescription you provided, we will remake them free within 30 days", "If there is a manufacturing defect (coating peeling, incorrect power), we replace at no charge", "Power correction: if you return for a power change within 30 days and your Rx was issued by us, lenses are remade free"], "heading": "Prescription Lenses — Not Returnable"}, {"icon": "🔵", "items": ["Sealed, unopened boxes may be exchanged within 7 days", "Once the box is opened, contact lenses cannot be returned for hygiene reasons", "Defective lenses (torn, damaged inside sealed pack) will be replaced"], "heading": "Contact Lenses — No Return Once Opened"}, {"icon": "📦", "items": ["Log in to My Account → My Orders → select order → Request Return (coming soon)", "Or WhatsApp us on 9840496404 with your order number", "We will arrange courier pickup from your address for orders above ₹2,000", "For smaller orders, you can return to either store directly", "Refund processed within 5–7 business days after we receive and inspect the item"], "heading": "Online Orders — Return Process"}]}', true, false, 32, '2026-11-22 06:05:08.117666+00'),
	('c4739583-3276-4ebb-a606-4438cecd9235', '00000000-0000-0000-0000-000000000001', 'contact', 'page', 'Contact Us', 'We would love to hear from you', NULL, '{"faqs": [{"a": "You can book online at powereyes.in/eye-test, call us on 9840496404, or walk into any of our Mogappair stores. Appointments are free.", "q": "How can I book an eye test?"}, {"a": "We accept UPI (Google Pay, PhonePe, Paytm), Credit/Debit Cards, Net Banking, and Cash on Delivery for select locations.", "q": "What payment methods do you accept?"}, {"a": "Yes, we accept valid prescriptions from any registered ophthalmologist or optometrist. Please bring the original prescription.", "q": "Do you accept prescriptions from other eye doctors?"}, {"a": "We offer easy returns within 7 days of purchase. Prescription glasses are eligible for lens power corrections within 30 days.", "q": "What is your return and exchange policy?"}, {"a": "Most single-vision glasses are ready in 2-3 days. Progressive or high-power lenses may take 5-7 working days.", "q": "How long does it take to get my glasses ready?"}, {"a": "Yes, we deliver across Chennai and major Indian cities. Free shipping on orders above ₹999. Express delivery is available for ₹99.", "q": "Do you offer home delivery?"}], "hours": "Mon - Sun: 10:00 AM - 9:00 PM"}', true, false, 34, '2026-11-22 06:05:08.117666+00'),
	('57d5bb16-694d-4a12-b965-6fdb4ecb37e8', '00000000-0000-0000-0000-000000000001', 'kids', 'page', 'Kids Eyewear', 'Safe, durable and stylish glasses for children', NULL, '{"ages": [{"desc": "Flexible hinges, soft nose pads, unbreakable TR90 frames", "label": "Pre-School", "range": "3–6 years"}, {"desc": "Spring hinges, wide bridge, comes with warranty", "label": "Primary", "range": "6–10 years"}, {"desc": "Teen styles, thinner lenses, premium brands", "label": "Middle School", "range": "10–14 years"}, {"desc": "Full adult frame styles with youth sizing", "label": "Teenage", "range": "14–17 years"}], "safety": [{"d": "Polycarbonate or Trivex lenses are 10× stronger than standard plastic — mandatory for children below 16.", "e": "🛡️", "t": "Impact Resistant"}, {"d": "TR90 and memory metal frames bend without breaking — ideal for active children.", "e": "🔧", "t": "Flexible Frames"}, {"d": "Recommended for school children who use tablets and computers for homework.", "e": "🔵", "t": "Blue Light Filter"}, {"d": "Bright colours, cartoon characters and patterns that children actually want to wear.", "e": "🎨", "t": "Fun Designs"}, {"d": "Hinges that flex outward reduce stress on the frame when children inevitably grab and bend them.", "e": "⚙️", "t": "Spring Hinges"}, {"d": "Comprehensive children''s eye test, free of charge, recommended annually from age 3.", "e": "📋", "t": "Free Kids Eye Test"}]}', true, false, 35, '2026-11-22 06:05:08.117666+00');
